mod field;mod jac;
use field::{F,E,P,Z,scalar,poly,trim,irreducible};use jac::{C,D};use std::collections::BTreeSet;
fn nums(s:&str)->Vec<u64>{s.split(|c:char|!c.is_ascii_digit()).filter(|s|!s.is_empty()).map(|s|s.parse().unwrap()).collect()}
fn sqroot(f:&F,a:E,z:E)->E{if a==Z{return Z}assert_eq!(f.pow(a,(f.q-1)/2),scalar(1));let mut q=f.q-1;let mut s=0;while q%2==0{q/=2;s+=1}let(mut c,mut x,mut t,mut m)=(f.pow(z,q),f.pow(a,(q+1)/2),f.pow(a,q),s);while t!=scalar(1){let mut i=0;let mut tt=t;while tt!=scalar(1){tt=f.mul(tt,tt);i+=1;assert!(i<m)}let b=f.pow(c,1u64<<(m-i-1));x=f.mul(x,b);c=f.mul(b,b);t=f.mul(t,c);m=i}assert_eq!(f.mul(x,x),a);x.min(f.sub(Z,x))}
fn compose(f:&F,a:&P,x:&P)->P{a.iter().rev().fold(vec![],|s,&v|f.pa(&f.pm(&s,x),&vec![v]))}
fn half(c:&C,a:E,rhos:&[E])->(D,P){let f=c.f;let mut e=vec![Z;rhos.len()+1];e[0]=scalar(1);for(i,&r)in rhos.iter().enumerate(){for j in(1..=i+1).rev(){e[j]=f.add(e[j],f.mul(r,e[j-1]))}}assert_eq!(e[9],Z);let t=vec![a,scalar(30)];let mut powers=vec![poly(&[1])];for i in 1..=4{powers.push(f.pm(&powers[i-1],&t))}let mut u=powers[4].clone();let mut v=vec![];for j in 1..=4{u=f.pa(&u,&c.scale(&powers[4-j],e[2*j]));v=f.pa(&v,&c.scale(&powers[4-j],f.sub(e[2*j+1],f.mul(e[1],e[2*j]))))}let vg=f.pa(&v,&c.scale(&u,e[1]));let d=D{u,v};(d,vg)}
fn digest(d:&D)->u64{let mut h=0xcbf29ce484222325u64;for p in[&d.u,&d.v]{h=(h^p.len()as u64).wrapping_mul(0x100000001b3);for a in p{for &x in a{h=(h^x).wrapping_mul(0x100000001b3)}}}h}
fn main(){
 let line=include_str!("../hec_g4_theta_admission_20261118/CONTROL.txt").lines().next().unwrap();let q4cs=nums(line.split("modulus=").nth(1).unwrap().split(']').next().unwrap());assert_eq!(q4cs,vec![28,0,29,10,1]);irreducible(31,&q4cs);let f4=F::new(31,q4cs.clone());let mut alpha=Z;alpha[1]=1;let shift=(0..31).find(|&k|f4.pow(f4.add(alpha,scalar(k)),(f4.q-1)/2)==scalar(30)).expect("no shifted nonsquare");
 let base=F::new(31,vec![0,1]);let arg=poly(&[(31-shift)%31,0,1]);let q8poly=compose(&base,&poly(&q4cs),&arg);let q8cs=q8poly.iter().map(|a|a[0]).collect::<Vec<_>>();irreducible(31,&q8cs);let f=F::new(31,q8cs.clone());let mut z=Z;z[1]=1;let mapped_alpha=f.sub(f.mul(z,z),scalar(shift));assert_eq!(f.eval(&poly(&q4cs),mapped_alpha),Z);assert_eq!(f.pow(z,(f.q-1)/2),scalar(30));
 let raw=nums(line.split("roots=").nth(1).unwrap());assert_eq!(raw.len(),81);let roots=raw.chunks(9).map(|a|{let mut r=Z;for &v in a.iter().rev(){r=f.add(f.mul(r,mapped_alpha),scalar(v))}r}).collect::<Vec<_>>();let c=C{f:&f,ff:poly(&[1,16,0,1,0,0,0,0,0,1]),g:4};let mut product=poly(&[1]);for(i,&r)in roots.iter().enumerate(){assert_eq!(f.eval(&c.ff,r),Z);for &q in &roots[..i]{assert_ne!(q,r)}product=f.pm(&product,&vec![f.sub(Z,r),scalar(1)])}assert_eq!(product,c.ff);println!("FIELD p=31 degree=8 shift={shift} modulus={q8cs:?} q={} source_embedding_alpha={mapped_alpha:?} roots={roots:?}",f.q);
 let mut selected=vec![];let(mut total,mut negative_rejected)=(0,0);for wi in 0..9{let a=roots[wi];let others=(0..9).filter(|&j|j!=wi).collect::<Vec<_>>();let rr=roots.iter().map(|&b|sqroot(&f,f.sub(a,b),z)).collect::<Vec<_>>();let branch=c.branch(a);let mut unique=BTreeSet::new();let mut first=None;for mask in 0..256usize{let mut rs=rr.clone();for(bit,&j)in others.iter().enumerate(){if mask&(1<<bit)!=0{rs[j]=f.sub(Z,rs[j])}}let(h,vg)=half(&c,a,&rs);assert!(c.valid(&h));assert_eq!(h.u.len(),5);assert!(h.v.len()<=4);assert_eq!(h.u.last(),Some(&scalar(1)));for &b in &roots{assert_ne!(f.eval(&h.u,b),Z)}let norm=f.ps(&c.ff,&f.pm(&vg,&vg));let expected=f.pm(&vec![f.sub(Z,a),scalar(1)],&f.pm(&h.u,&h.u));assert_eq!(norm,expected,"principal half identity");assert_eq!(c.add(&h,&h),branch);assert_eq!(c.mul(&h,4),c.zero());assert_ne!(h,c.zero());assert!(unique.insert(h.clone()),"duplicate half");
 let mut bad=h.clone();if bad.v.is_empty(){bad.v=poly(&[1])}else{bad.v[0]=f.add(bad.v[0],scalar(1));bad.v=trim(bad.v)}if !c.valid(&bad){negative_rejected+=1}
 println!("HALF wi={wi} mask={mask} digest={:016x} principal=true double=true order4=true",digest(&h));if mask==0{first=Some(h)}total+=1;
 }assert_eq!(unique.len(),256);let first=first.unwrap();let negative=c.neg(&first);assert!(unique.contains(&negative));let degree=[1u32,2,4,8].into_iter().find(|&d|[&first.u,&first.v].into_iter().flatten().all(|&a|f.pow(a,31u64.pow(d))==a)).unwrap();println!("SELECTED wi={wi} half_field_degree={degree} u={:?} v={:?}",first.u,first.v);selected.push(first);}
 assert_eq!(total,2304);assert!(negative_rejected>0);
 let generators=[selected[0].clone(),c.add(&selected[1],&selected[3]),c.add(&selected[2],&selected[4]),c.add(&selected[5],&selected[7])];let masks=[1u8,10,20,160];for(i,h)in generators.iter().enumerate(){let mut expected=c.zero();for j in 0..8{if masks[i]&(1<<j)!=0{expected=c.add(&expected,&c.branch(roots[j]))}}assert_eq!(c.add(h,h),expected);println!("KERNEL_HALF basis={} u={:?} v={:?} isotropy_unchecked=true",masks[i],h.u,h.v)}
 let mut subgroup=BTreeSet::new();let mut doubled=BTreeSet::new();for coeff in 0..256usize{let mut d=c.zero();for j in 0..4{d=c.add(&d,&c.mul(&generators[j],(coeff>>(2*j))&3))}assert!(c.valid(&d));assert!(subgroup.insert(d.clone()));doubled.insert(c.add(&d,&d));}assert_eq!(subgroup.len(),256);assert_eq!(doubled.len(),16);
 let mut native_kernel=BTreeSet::new();for bits in 0..16usize{let mut d=c.zero();for j in 0..4{if bits&(1<<j)!=0{d=c.add(&d,&c.add(&generators[j],&generators[j]))}}native_kernel.insert(d);}assert_eq!(doubled,native_kernel);
 println!("PASS halves={total} distinct_per_branch=256 principal_identities=2304 cantor_doubles=2304 order4_checks=2304 altered_v_rejected={negative_rejected} kernel_lift_group_size=256 doubled_kernel_size=16 isotropy_checked=false theta_structure_computed=false");
}
